import * as THREE from 'three';

const canvas=document.querySelector('#game-canvas');
const scene=new THREE.Scene();scene.background=new THREE.Color(0x9ca99e);scene.fog=new THREE.Fog(0x9ca99e,170,690);
const camera=new THREE.PerspectiveCamera(56,innerWidth/innerHeight,.1,1100);
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.65));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.12;
scene.add(new THREE.HemisphereLight(0xdbe7ed,0x444943,2));const sun=new THREE.DirectionalLight(0xffe1b4,3.2);sun.position.set(-120,190,90);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);sun.shadow.camera.left=-160;sun.shadow.camera.right=160;sun.shadow.camera.top=160;sun.shadow.camera.bottom=-160;scene.add(sun);
const mat=(color,rough=.8,metal=0)=>new THREE.MeshStandardMaterial({color,roughness:rough,metalness:metal});
const mats={ground:mat(0x657963),road:mat(0x343a3b),side:mat(0xb3a99a),line:mat(0xd4c59d),glass:mat(0x283a40,.28,.4),window:mat(0x9ba9a6,.35,.1),leaf:mat(0x405e4c),trunk:mat(0x594638),white:mat(0xd3cfc3),gold:mat(0xd4a753,.36,.4)};
const ground=new THREE.Mesh(new THREE.PlaneGeometry(1100,1100),mats.ground);ground.rotation.x=-Math.PI/2;ground.position.y=-.12;ground.receiveShadow=true;scene.add(ground);
const world=new THREE.Group();scene.add(world);const buildings=[],cars=[],npcs=[],landmarks=[];
function box(parent,w,h,d,material,x,y,z,cast=true){const o=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),material);o.position.set(x,y,z);o.castShadow=cast;o.receiveShadow=true;parent.add(o);return o}
function cylinder(parent,r1,r2,h,material,x,y,z,segments=8){const o=new THREE.Mesh(new THREE.CylinderGeometry(r1,r2,h,segments),material);o.position.set(x,y,z);o.castShadow=true;parent.add(o);return o}
function seeded(seed){let s=seed|0;return()=>{s=(s*1664525+1013904223)|0;return(s>>>0)/4294967296}}
// A continuous grid city: districts share roads and utilities, so there are no world transitions.
box(world,1100,.22,1100,mats.ground,0,-.25,0,false);
for(let v=-500;v<=500;v+=100){
  box(world,16,.035,1100,mats.road,v,.005,0,false);box(world,3,.04,1100,mats.side,v-9,.01,0,false);box(world,3,.04,1100,mats.side,v+9,.01,0,false);
  box(world,1100,.035,16,mats.road,0,.006,v,false);box(world,1100,.04,3,mats.side,0,.01,v-9,false);box(world,1100,.04,3,mats.side,0,.01,v+9,false);
  if(v%200===0){for(let z=-480;z<500;z+=26)box(world,1.2,.045,10,mats.line,v,.04,z,false);for(let x=-480;x<500;x+=26)box(world,10,.045,1.2,mats.line,x,.04,v,false)}
}
// District blocks, with layered rooftops, warm window bands and occasional corner trees.
const colors=[0x747b79,0x8c8580,0x727d7b,0x958c7c,0x656e70,0x9a8873,0x777e70,0x777477];
let bid=0;
for(let ix=-4;ix<=4;ix++)for(let iz=-4;iz<=4;iz++){
 const bx=ix*100,bz=iz*100,r=seeded((ix+8)*997+(iz+8)*71+43);
 if(Math.abs(bx)<60&&Math.abs(bz)<60)continue;
 const downtown=Math.abs(bx)<160&&Math.abs(bz)<160;
 const count=downtown?3:2;
 for(let j=0;j<count;j++){
  const x=bx+(r()-.5)*53,z=bz+(r()-.5)*53,w=17+r()*20,d=18+r()*18;
  let h=downtown?26+r()*88:12+r()*37;if(ix>2&&iz>2)h*=.55;
  const color=colors[Math.floor(r()*colors.length)],g=new THREE.Group();world.add(g);
  box(g,w,h,d,mat(color),0,h/2,z*0,false); // local building body, repositioned below
  g.position.set(x,0,z);g.children[0].position.z=0;g.children[0].receiveShadow=true;
  // stepped roof crown and facade strips
  if(h>45){box(g,w*.7,2,d*.7,mat(color-0x080808),0,h+1,0);box(g,w*.35,5,d*.35,mat(color-0x101010),0,h+4,0)}
  const levels=Math.min(8,Math.floor(h/5));
  for(let k=0;k<levels;k++){
   const yy=3+k*(h/levels);
   const wm=mat(r()>.12?0x9caaa2:0xb1a778,.4,.1);
   // two readable window ribbons, not full facade tiling
   box(g,w*.77,.65,.11,wm,0,yy,d/2+.065,false);box(g,.11,.65,d*.72,wm,w/2+.065,yy,0,false);
  }
  buildings.push(g);bid++;
 }
 // street trees & lamp posts on sparse block corners
 if((ix+iz)%3===0){const tx=bx+38,tz=bz+34;cylinder(world,.35,.48,5,mats.trunk,tx,2.5,tz,6);const crown=new THREE.Mesh(new THREE.IcosahedronGeometry(3.2,1),mats.leaf);crown.position.set(tx,6,tz);crown.castShadow=true;world.add(crown)}
}
// Landmarks give the districts recognizable silhouettes and useful destinations.
function signBlock(x,z,w,d,h,color,label){const grp=new THREE.Group();world.add(grp);box(grp,w,h,d,mat(color),x,h/2,z);box(grp,w*.58,1.1,.5,mats.gold,x,h+1,z+d/2+.3);landmarks.push({x,z,label,group:grp});return grp}
