}
function landmark(x,z,w,d,h,color,label){const group=new THREE.Group();world.add(group);box(group,w,h,d,mat(color),x,h/2,z);box(group,w*.58,1.1,.5,mats.gold,x,h+1,z+d/2+.3);landmarks.push({x,z,label,group});}
